fault_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/35f6cb77be23/fault.log 2>&1
test "$(hostname -s)" = srv01
ip -j -4 address show dev enp0s8 | python3 -c 'import json,sys; assert any(a.get("local")=="192.168.56.20" for link in json.load(sys.stdin) for a in link.get("addr_info",[]))'

echo FAULT_BEFORE $(date -u +%s)

systemd-run --unit=mlv2-stress-35f6cb77be23 --property=RuntimeMaxSec=450s /usr/bin/stress-ng --cpu "$(nproc)" --cpu-load 100 --timeout 420s --metrics-brief
sleep 1; systemctl is-active mlv2-stress-35f6cb77be23.service
echo FAULT_VERIFIED $(date -u +%s)

rollback_script:
#!/bin/bash
set -euo pipefail
exec >>/home/phat/ml-experiments/35f6cb77be23/rollback.log 2>&1
echo ROLLBACK_BEFORE $(date -u +%s)
if [ "$(systemctl show --property=LoadState --value mlv2-stress-35f6cb77be23.service)" != not-found ]; then
  systemctl stop mlv2-stress-35f6cb77be23.service
fi
echo ROLLBACK_AFTER $(date -u +%s)
